( @ExpenseIds NVARCHAR(MAX), @ActorUserId BIGINT = NULL, @ActorIsSystemAdmin BIT = 0 ) AS BEGIN SET NOCOUNT ON; SELECT e.[Id] AS [ExpenseId], cs.[PublicId] AS [CodingItemPublicId], cs.[Status], cs.[SuggestionConfidence], cs.[SuggestedProjectId], cs.[SuggestedSubCostCodeId], cs.[ConfirmedProjectId], cs.[ConfirmedSubCostCodeId], cs.[FlagReason] FROM dbo.[CodingSuggestion] cs INNER JOIN dbo.[Expense] e ON ( cs.[ExpenseId] IS NOT NULL AND e.[Id] = cs.[ExpenseId] ) OR ( cs.[ExpenseId] IS NULL AND cs.[QboPurchaseQboId] IS NOT NULL AND cs.[RealmId] IS NOT NULL AND e.[QboId] = cs.[QboPurchaseQboId] AND e.[RealmId] = cs.[RealmId] ) INNER JOIN STRING_SPLIT(ISNULL(@ExpenseIds, ''), ',') s ON s.value <> '' AND e.[Id] = TRY_CAST(LTRIM(RTRIM(s.value)) AS BIGINT) WHERE EXISTS ( SELECT 1 FROM dbo.[ExpenseLineItem] eli INNER JOIN qbo.[Purchase] p ON p.[QboId] = e.[QboId] AND p.[RealmId] = e.[RealmId] INNER JOIN qbo.[PurchaseLine] pl ON pl.[QboPurchaseId] = p.[Id] AND pl.[QboLineId] = eli.[QboId] AND eli.[RealmId] = p.[RealmId] WHERE eli.[ExpenseId] = e.[Id] ) AND ( @ActorIsSystemAdmin = 1 OR COALESCE(cs.[ConfirmedProjectId], cs.[SuggestedProjectId]) IS NULL OR dbo.UserCanAccessProject( @ActorUserId, @ActorIsSystemAdmin, COALESCE(cs.[ConfirmedProjectId], cs.[SuggestedProjectId])) = 1 ); END;
